menu = [('Search', 'always'), ('Share', 'ifRoom'), ('Edit', 'ifRoom'), ('Delete', 'ifRoom'), ('Settings', 'never')]
room = 3
bar = []
overflow = []
for name, mode in menu:
    if mode == 'always':
        bar.append(name)
    elif mode == 'never':
        overflow.append(name)
    else:
        if len(bar) < room:
            bar.append(name)
        else:
            overflow.append(name)
print(len(bar))
print(len(overflow))
